const root=document.querySelector('#report');let request=0;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function link(text,url){const n=el('a',text);n.href=url;n.setAttribute('download','');return n}
async function load(mode){const id=++request;for(const m of ['buggy','fixed','limited'])document.getElementById(m).setAttribute('aria-pressed',String(m===mode));root.textContent='Loading recorded run…';try{const base=`policy-runs/${mode}/`;const response=await fetch(base+'report.json');if(!response.ok)throw Error('Report unavailable');const r=await response.json();if(id!==request)return;root.replaceChildren();const summary=el('div',undefined,'summary');const titles={confirmed:'Failure reproduced independently',passed:'Empty-cart contract passed',inconclusive:'Step limit reached — no finding'};summary.append(el('strong',titles[r.verdict]||r.verdict),el('p',`Offline mock policy · ${new Date(r.created_at).toLocaleString()} · real Chromium execution`));const metrics=el('div',undefined,'metrics');for(const [k,v] of [['Policy decisions',r.policy.decision_calls],['Browser actions',r.actions.length],['API requests',r.policy.api_requests],['Stop reason',r.phases.exploration.stop_reason]]){const n=el('span',k);n.append(el('b',String(v)));metrics.append(n)}summary.append(metrics);const files=el('div',undefined,'links');files.append(link('Full report',base+'report.json'),link('Replay actions',base+'actions.json'));if(r.regression)files.append(link('Regression script',base+r.regression));summary.append(files);root.append(summary);const grid=el('div',undefined,'grid');const timeline=el('section',undefined,'panel');timeline.append(el('h2','01 / Observe → decide → act'));const body=el('div',undefined,'body');for(const d of r.phases.exploration.decisions){const item=el('div',undefined,'decision');item.append(el('small',`STEP ${d.step} · ${d.observation.quantity} items · ${d.observation.displayed_total}`),el('h3',d.decision.type==='stop'?'Stop':d.decision.name),el('p',d.decision.summary));body.append(item)}timeline.append(body);grid.append(timeline);const replay=el('section',undefined,'panel');replay.append(el('h2','02 / Replay without the policy'));const rb=el('div',undefined,'body');const p=r.phases.replay;rb.append(el('p',`Fresh browser context. Replayed ${p.actions.length} recorded actions. No policy decisions during verification.`),el('h3',`${p.final.quantity} items · ${p.final.displayed_total}`),el('p',`Contract result: ${p.contract.status}.`));const img=el('img');img.src=base+p.screenshots.at(-1);img.alt=`Replay ends at ${p.final.quantity} items and ${p.final.displayed_total}`;rb.append(img);const downloads=el('div',undefined,'links');downloads.append(link('Browser trace',base+p.trace),link('Replay log',base+'replay/events.json'),link('Exploration log',base+'exploration/events.json'));rb.append(downloads);replay.append(rb);grid.append(replay);root.append(grid)}catch(e){if(id===request)root.textContent=`Cannot load evidence: ${e.message}`}}
for(const m of ['buggy','fixed','limited'])document.getElementById(m).onclick=()=>load(m);load('buggy');
